```cypher
MATCH (s:Set)
WHERE EXISTS {
  MATCH (s)-[:EXPLODES {is_current: true}]->(m:Minifig)
  WHERE m.fig_num = 'fig-001375'
}
AND EXISTS {
  MATCH (s)-[:EXPLODES {is_current: true}]->(p:Part)
  WHERE p.part_num = '3298'
}
RETURN COUNT(DISTINCT s.set_num) AS count
```

```cypher
MATCH (targetSet:Set)
WHERE EXISTS {
  MATCH (targetSet)-[:EXPLODES*1..10]->(m:Minifig {fig_num: 'fig-008097'})
  WHERE e.is_current = true
}
AND EXISTS {
  MATCH (targetSet)-[:EXPLODES*1..10]->(p:Part {part_num: '99206'})
  WHERE e.is_current = true AND e.is_spare = false
}
RETURN count(targetSet) AS num_sets
```

```cypher
MATCH (targetSet:Set)
WHERE EXISTS {
  MATCH (targetSet)-[e:EXPLODES*1..10]->(m:Minifig {fig_num: 'fig-008097'})
  WHERE ALL(r IN rels(e) | r.is_current = true)
}
AND EXISTS {
  MATCH (targetSet)-[e2:EXPLODES*1..10]->(p:Part {part_num: '99206'})
  WHERE ALL(r IN rels(e2) | r.is_current = true) AND ALL(r IN rels(e2) | r.is_spare = false)
}
RETURN count(targetSet) AS num_sets
```

```cypher
MATCH (targetMinifig:Minifig {fig_num: 'fig-004305'}), (targetPart:Part {part_num: '3033'})
MATCH (s:Set)
WHERE EXISTS {
    MATCH (s)-[:EXPLODES*1..10]->(targetMinifig)
    WHERE rels(s)-[:EXPLODES]->(targetMinifig).is_spare = FALSE OR rels(s)-[:EXPLODES]->(targetMinifig).is_spare IS NULL
}
AND EXISTS {
    MATCH (s)-[:EXPLODES*1..10]->(targetPart)
    WHERE rels(s)-[:EXPLODES]->(targetPart).is_spare = FALSE
}
RETURN COUNT(DISTINCT s.set_num) AS num_sets
